schema_ddl:
CREATE TABLE clienti (
    cliente_id INT PRIMARY KEY,
    ragione_sociale TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE,
    citta TEXT NOT NULL
);

CREATE TABLE vettori (
    vettore_id INT PRIMARY KEY,
    denominazione TEXT NOT NULL,
    codice_abilitazione TEXT NOT NULL UNIQUE,
    telefono_contatto TEXT
);

CREATE TABLE magazzini (
    magazzino_id INT PRIMARY KEY,
    nome_deposito TEXT NOT NULL,
    capacita_pallet INT NOT NULL CHECK (capacita_pallet > 0),
    citta TEXT NOT NULL
);

CREATE TABLE spedizioni (
    spedizione_id INT PRIMARY KEY,
    vettore_id INT NOT NULL REFERENCES vettori(vettore_id),
    magazzino_id INT NOT NULL REFERENCES magazzini(magazzino_id),
    cliente_id INT NOT NULL REFERENCES clienti(cliente_id),
    data_spedizione DATE NOT NULL,
    peso_totale_kg NUMERIC(10,2) NOT NULL CHECK (peso_totale_kg >= 0),
    stato_consegna TEXT NOT NULL CHECK (stato_consegna IN ('pianificata', 'in_transito', 'consegnata', 'fallita'))
);

CREATE TABLE colli (
    collo_id INT PRIMARY KEY,
    spedizione_id INT NOT NULL REFERENCES spedizioni(spedizione_id),
    peso_collo_kg NUMERIC(8,2) NOT NULL CHECK (peso_collo_kg > 0),
    descrizione_contenuto TEXT
);
